import itertools
import json

def build_adjacency(edges):
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    return adj

def compute_ranges(order, durations):
    # Overlap-on-travel: next start equals current end (flight day counted in both)
    ranges = {}
    s = 1
    for city in order:
        e = s + durations[city] - 1
        ranges[city] = (s, e)
        s = e  # next city starts on the same day current ends (overlap by 1)
    return ranges

def valid_connectivity(order, adj):
    return all(order[i+1] in adj.get(order[i], set()) for i in range(len(order)-1))

def windows_satisfied(ranges, time_windows):
    for city, (ws, we) in time_windows.items():
        s, e = ranges[city]
        if not (s <= ws and e >= we):
            return False
    return True

def total_days_ok(order, ranges, total_days):
    last_city = order[-1]
    return ranges[last_city][1] == total_days

def find_itinerary(cities, durations, edges, time_windows, total_days):
    # Sanity check: total_days must equal sum(durations) - (num_cities - 1) to allow exactly one-day overlaps per flight
    if sum(durations.values()) - (len(cities) - 1) != total_days:
        return None

    adj = build_adjacency(edges)

    # To reduce search space, we ensure Mykonos includes Day 1 (wedding), so it must be first.
    start_city = "Mykonos"
    if start_city not in cities:
        return None

    others = [c for c in cities if c != start_city]
    # Deterministic search: try permutations of remaining cities in alphabetical order
    for perm in itertools.permutations(sorted(others)):
        order = [start_city] + list(perm)
        if not valid_connectivity(order, adj):
            continue
        ranges = compute_ranges(order, durations)
        if not total_days_ok(order, ranges, total_days):
            continue
        if not windows_satisfied(ranges, time_windows):
            continue
        # Found a valid itinerary
        return order, ranges

    return None

def main():
    # Input variables (constraints)
    cities = ["Mykonos", "Zurich", "Prague", "Valencia", "Bucharest", "Riga", "Nice"]
    durations = {
        "Valencia": 5,
        "Riga": 5,
        "Prague": 3,
        "Mykonos": 3,
        "Zurich": 5,
        "Bucharest": 5,
        "Nice": 2
    }
    total_days = 22
    # Time windows constraints: inclusive days that must be within the stay
    time_windows = {
        "Mykonos": (1, 3),   # Wedding between Day 1-3
        "Prague": (7, 9)     # Relatives visit between Day 7-9
    }
    # Direct flights (undirected)
    edges = [
        ("Mykonos", "Nice"),
        ("Mykonos", "Zurich"),
        ("Prague", "Bucharest"),
        ("Valencia", "Bucharest"),
        ("Zurich", "Prague"),
        ("Riga", "Nice"),
        ("Zurich", "Riga"),
        ("Zurich", "Bucharest"),
        ("Zurich", "Valencia"),
        ("Bucharest", "Riga"),
        ("Prague", "Riga"),
        ("Prague", "Valencia"),
        ("Zurich", "Nice")
    ]

    result = find_itinerary(cities, durations, edges, time_windows, total_days)
    if result is None:
        output = {"error": "No feasible itinerary found with given constraints."}
    else:
        order, ranges = result
        itinerary = []
        for city in order:
            s, e = ranges[city]
            itinerary.append({"day_range": f"Day {s}-{e}", "place": city})
        output = {"itinerary": itinerary}

    print(json.dumps(output))

if __name__ == "__main__":
    main()
